questions.solution:
type Middleware<C, R> = (context: C, next: () => Promise<R>) => Promise<R>;

function compose<C, R>(middleware: Middleware<C, R>[], handler: (context: C) => Promise<R>): (context: C) => Promise<R> {
  return (context) => {
    const dispatch = (index: number): Promise<R> => {
      const current = middleware[index];
      if (!current) return handler(context);
      let called = false;
      return current(context, () => {
        if (called) return Promise.reject(new Error("next() called twice"));
        called = true;
        return dispatch(index + 1);
      });
    };
    return dispatch(0);
  };
}

const trace = (name: string): Middleware<{ log: string[] }, string> => async (context, next) => {
  context.log.push(`${name} in`);
  const result = await next();
  context.log.push(`${name} out`);
  return result;
};
const context = { log: [] as string[] };
const run = compose([trace("auth"), trace("validate")], async (c) => {
  c.log.push("handler");
  return "paid";
});
console.log(await run(context), context.log.join(" > "));

const twice = compose<{ log: string[] }, string>([async (_c, next) => { await next(); return next(); }], async () => "paid");
console.log(await twice({ log: [] }).catch((error: Error) => error.message));

