function createLimiter(max: number, windowMs: number) {
  const seen = new Map<string, number[]>();
  return {
    allow(key: string, now: number): boolean {
      const recent = (seen.get(key) ?? []).filter((time) => now - time < windowMs);
      if (recent.length >= max) {
        seen.set(key, recent);
        return false;
      }
      recent.push(now);
      seen.set(key, recent);
      return true;
    },
  };
}

const limiter = createLimiter(2, 60_000);
const at = (seconds: number) => seconds * 1000;
console.log(
  [limiter.allow("ada", at(0)), limiter.allow("ada", at(30)), limiter.allow("ada", at(59)), limiter.allow("bayo", at(59)), limiter.allow("ada", at(61))].join(" "),
);

