questions.solution:
function toStatus(error: unknown): string {
  if (typeof error !== "object" || error === null) return "500";
  const candidate = error as { retryAfterMs?: unknown; expose?: unknown; statusCode?: unknown };
  if (typeof candidate.retryAfterMs === "number") {
    return `429 retry-after=${Math.ceil(candidate.retryAfterMs / 1000)}`;
  }
  if (candidate.expose === true && typeof candidate.statusCode === "number" && candidate.statusCode < 500) {
    return String(candidate.statusCode);
  }
  return "500";
}

console.log(toStatus({ retryAfterMs: 59_001 }));
console.log(toStatus({ expose: true, statusCode: 403 }));
console.log(toStatus({ expose: false, statusCode: 401 }));
console.log(toStatus(new Error("connection refused")));
console.log(toStatus("not an error"));

