function dailyCap(capKobo: number) {
  const totals = new Map<string, number>();
  return (userId: string, amountKobo: number, next: () => string): string => {
    const already = totals.get(userId) ?? 0;
    if (already + amountKobo > capKobo) return "refused";
    const result = next();
    if (result === "ok") totals.set(userId, already + amountKobo);
    return result;
  };
}

const cap = dailyCap(10_000_000);
console.log(
  [
    cap("ada", 4_500_000, () => "ok"),
    cap("ada", 4_500_000, () => "insufficient funds"),
    cap("ada", 4_500_000, () => "ok"),
    cap("ada", 4_500_000, () => "ok"),
    cap("bayo", 4_500_000, () => "ok"),
  ].join(", "),
);

